/bin/zsh -lc "python -c 'import urllib.request,json
for u in [\"https://api.figshare.com/v2/articles/29472362/versions\", \"https://api.github.com/repos/broadinstitute/DepMap-NextGen-Public/git/trees/main?recursive=1\"]:
 print(\"URL\",u)
 try:
  d=json.load(urllib.request.urlopen(u,timeout=20))
  if isinstance(d,dict) and \"tree\" in d:
   print(\"sha\",d[\"sha\"])
   for x in d[\"tree\"]: print(x[\"path\"],x.get(\"size\",\"\"),x[\"type\"])
  else: print(json.dumps(d))
 except Exception as e: print(type(e).__name__,str(e))'"

